<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Models\Upload;
use App\Services\UnusedImageCleaner as Cleaner;
class MediaCenterController extends Controller {
 private function access(){ $u=auth()->user();abort_unless($u&&!$u->banned&&($u->user_type==='admin'||($u->user_type==='staff'&&in_array('22',json_decode($u->staff->role->permissions??'[]',true)?:[],true))),403);}
 public function index(Request $r){$this->access();$f=$r->validate(['q'=>'nullable|string|max:100','type'=>'nullable|in:image,video,audio,document,archive,other','sort'=>'nullable|in:newest,oldest,smallest,largest','from'=>'nullable|date_format:Y-m-d','to'=>array_filter(['nullable','date_format:Y-m-d',$r->filled('from')?'after_or_equal:from':null]),'usage'=>'nullable|in:product,not-product','min_kb'=>'nullable|integer|min:0|max:10000000','max_kb'=>'nullable|integer|min:0|max:10000000','tab'=>'nullable|in:trash']);$trashIds=Cleaner::quarantinedIds();$q=Upload::query()->whereNotIn('id',$trashIds);if(!empty($f['q'])){$term=str_replace(['!','%','_'],['!!','!%','!_'],$f['q']);$q->whereRaw("file_original_name LIKE ? ESCAPE '!'",['%'.$term.'%']);}if(!empty($f['type'])){if($f['type']==='other')$q->whereNotIn('type',['image','video','audio','document','archive']);else $q->where('type',$f['type']);}if(!empty($f['from']))$q->where('created_at','>=',$f['from'].' 00:00:00');if(!empty($f['to']))$q->where('created_at','<=',$f['to'].' 23:59:59');if(isset($f['min_kb']))$q->where('file_size','>=',$f['min_kb']*1024);if(isset($f['max_kb']))$q->where('file_size','<=',$f['max_kb']*1024);
 if(!empty($f['usage'])){$method=$f['usage']==='product'?'whereExists':'whereNotExists';$q->$method(function($p){$p->select(DB::raw(1))->from('products')->where(function($p){$p->whereColumn('products.thumbnail_img','uploads.id')->orWhereColumn('products.meta_img','uploads.id')->orWhereRaw('FIND_IN_SET(uploads.id, products.photos)>0');});});}
 $sort=$f['sort']??'newest';$q->orderBy(in_array($sort,['smallest','largest'],true)?'file_size':'created_at',in_array($sort,['oldest','smallest'],true)?'asc':'desc')->orderBy('id');$files=$q->paginate(48)->withQueryString();$trash=Cleaner::quarantined();$totals=Upload::whereNotIn('id',$trashIds)->selectRaw('type, COUNT(*) count, COALESCE(SUM(file_size),0) bytes')->groupBy('type')->get();return view('backend.media_center.index',compact('files','f','trash','totals'));}
 public function action(Request $r){$this->access();abort_unless(auth()->user()->user_type==='admin',403);$d=$r->validate(['action'=>'required|in:quarantine,restore,permanent','ids'=>'required|array|min:1|max:5','ids.*'=>'required|string|max:80|distinct']);$results=[];foreach($d['ids'] as $id){try{if($d['action']==='quarantine'){abort_unless(ctype_digit((string)$id),422);$result=Cleaner::quarantine((int)$id);}elseif($d['action']==='restore')$result=Cleaner::restore($id);else $result=Cleaner::permanent($id);$results[]=['id'=>$id,'ok'=>true,'message'=>$d['action']==='quarantine'?'Moved to Trash / Trash-এ গেছে':($d['action']==='restore'?'Restored / ফিরে এসেছে':'Permanently deleted / মুছে গেছে'),'reference'=>$result['reference']??null];}catch(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface $e){$results[]=['id'=>$id,'ok'=>false,'message'=>$e->getMessage()?:'Media retained.'];}catch(\Throwable $e){$results[]=['id'=>$id,'ok'=>false,'message'=>'Media retained: reference/storage check could not finish.'];}}return response()->json(['results'=>$results])->header('Cache-Control','private, no-store');}
}
